insert into public.profiles(id,display_name,role,active) values ('e0000000-0000-0000-0000-000000000001','Admin','admin',true),('e0000000-0000-0000-0000-000000000002','Worker','collaborator',true);
insert into public.customers(id,name) values ('e0000000-0000-0000-0000-000000000003','Historical customer');
insert into public.products(id,name) values ('e0000000-0000-0000-0000-000000000004','Historical product');
insert into public.sales_orders(id,operation_key,customer_id,product_id,ordered_on,quantity,unit_price,actor_id) values ('e0000000-0000-0000-0000-000000000005','e0000000-0000-0000-0000-000000000006','e0000000-0000-0000-0000-000000000003','e0000000-0000-0000-0000-000000000004','2026-01-01',4,100,'e0000000-0000-0000-0000-000000000001');
set local role authenticated;
select set_config('request.jwt.claim.sub','e0000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.record_historical_customer_payment('e0000000-0000-0000-0000-000000000007','e0000000-0000-0000-0000-000000000005','2026-01-01',100,'Desconocido','Fecha provisoria')$$,'dated historical payment recorded');
select lives_ok($$select public.record_historical_customer_payment('e0000000-0000-0000-0000-000000000008','e0000000-0000-0000-0000-000000000005',null,100,'Desconocido','Fecha desconocida')$$,'undated historical payment recorded');
select lives_ok($$select public.record_historical_customer_payment('e0000000-0000-0000-0000-000000000008','e0000000-0000-0000-0000-000000000005',null,100,'Desconocido','Fecha desconocida')$$,'payment retry is idempotent');
select is((select count(*) from public.customer_payments),2::bigint,'retry does not duplicate payment');
select is((select paid from public.sales_order_payment_progress),200::numeric,'both payments reduce order balance');
select is((select count(*) from public.financial_transactions),1::bigint,'only dated payment appears in cash');
select is((select notes from public.financial_transactions),'Fecha provisoria','cash retains provisional date warning');
select throws_ok($$select public.record_customer_payment('e0000000-0000-0000-0000-000000000008','e0000000-0000-0000-0000-000000000005','2026-01-01',100,'Desconocido','Fecha desconocida')$$,'P0001','operation key already used','regular payment cannot reuse historical key');
select throws_ok($$select public.record_historical_customer_payment('e0000000-0000-0000-0000-000000000008','e0000000-0000-0000-0000-000000000005','2026-01-01',100,'Desconocido','Fecha desconocida')$$,'P0001','operation key already used','retry cannot change unknown date');
select lives_ok($$select public.record_historical_order_delivery('e0000000-0000-0000-0000-000000000009','e0000000-0000-0000-0000-000000000005',2,'Fecha desconocida')$$,'historical delivery recorded');
select lives_ok($$select public.record_historical_order_delivery('e0000000-0000-0000-0000-000000000009','e0000000-0000-0000-0000-000000000005',2,'Fecha desconocida')$$,'delivery retry is idempotent');
select is((select delivered from public.order_delivery_progress),2::bigint,'historical delivery counts for order');
select is((select delivered from public.finished_stock),0::bigint,'historical delivery does not consume stock');
select throws_ok($$select public.deliver_order('e0000000-0000-0000-0000-000000000009','e0000000-0000-0000-0000-000000000005','2026-01-01',2,'Fecha desconocida')$$,'P0001','operation key already used','regular delivery cannot reuse historical key');
select throws_ok($$select public.deliver_order('e0000000-0000-0000-0000-000000000010','e0000000-0000-0000-0000-000000000005','2026-01-01',1,'')$$,'P0001','insufficient finished stock','historical delivery does not create stock');
select lives_ok($$select public.reverse_linked_payment('e0000000-0000-0000-0000-000000000011','customer',(select id from public.customer_payments where paid_on is null),'2026-01-02','Correccion')$$,'undated historical payment can be reversed without inventing cash');
select is((select paid from public.sales_order_payment_progress),100::numeric,'reversal restores balance');
select is((select count(*) from public.financial_transactions),1::bigint,'reversal has no fictitious cash entry');
select set_config('request.jwt.claim.sub','e0000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.record_historical_customer_payment('e0000000-0000-0000-0000-000000000012','e0000000-0000-0000-0000-000000000005',null,1,'x','')$$,'42501','access denied','worker cannot import payments');
select throws_ok($$select public.record_historical_order_delivery('e0000000-0000-0000-0000-000000000013','e0000000-0000-0000-0000-000000000005',1,'')$$,'42501','access denied','worker cannot import deliveries');
select * from finish();
rollback;
